# --- Configuration ---
# The final, sorted log file generated by `run_full_test.py`
MERGED_LOG_FILE = 'merged_test_run.log'
# The output CSV file
OUTPUT_CSV_FILE = 'performance_analysis.csv'

# --- Event Definitions ---
# This is the core logic. We define rules to identify the start and end of each event
# we want to measure. Each rule contains:
# - 'event_name': The name that will appear in the CSV.
# - 'start_regex': A regex to find the log line that starts the event.
# - 'end_regex': A regex to find the log line that ends the event.
# - 'id_regex': (Optional) A regex to extract a unique ID to match start/end pairs (e.g., a task ID).

# This regex will match either a UUID or a LONG_TASK_ID
# e.g., "686a6bf9-8cfb-4088-a492-06f8b3b50a2b" or "LONG_TASK_1"
UUID_OR_LONG_TASK_REGEX = r'(?:[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}|LONG_TASK_\d+)'
THREAD_ID_REGEX = r'\d+\s+\d+' # Captures the two numbers representing thread IDs

EVENT_RULES = [
    {
        # Measures the full round-trip time from the client's perspective for a long task.
        'event_name': 'CLIENT_ROUND_TRIP_LONG_TASK',
        'start_regex': r'\[CLIENT\] \[(LONG_TASK_\d+)\] ---> Sending request...',
        # This end event is tricky because the final response is polled for, not directly received.
        # We will use the "Task complete!" log from the client polling script.
        'end_regex': r'\[CLIENT\] \[(LONG_TASK_\d+)\].*Task complete!',
        'id_regex': r'(LONG_TASK_\d+)'
    },
    {
        # Measures the time from when a client sends a request until the server
        # assigns it a UUID and logs that it has started handling the request.
        'event_name': 'NETWORK_LATENCY_AND_SERVER_ACCEPTANCE',
        'start_regex': r'\[CLIENT\] \[(LONG_TASK_\d+)\] ---> Sending request...',
        # This now correctly looks for the server's initial handling log.
        'end_regex': r'\[SERVER\].* I TestServer: Handling: POST /recognize for task (' + UUID_OR_LONG_TASK_REGEX + r')',
        'is_linking_rule': True
        # A better metric is to measure from when the server starts handling to when it queues.
    },
    {
        # This now specifically measures the artificial delay period for testing.
        'event_name': 'SERVER_ARTIFICIAL_DELAY',
        'start_regex': r'\[SERVER\].*\[(' + UUID_OR_LONG_TASK_REGEX + r')\] - Starting 8-second artificial delay',
        'end_regex': r'\[SERVER\].*I ImageRecognizer: Detection complete.', # Ends when detection is done
        'id_regex': None
    },
    {
        # Measures the time from when the model finishes to when the server releases the permit.
        # This captures the final result handling and cleanup.
        'event_name': 'SERVER_RESULT_HANDLING_TIME',
        'start_regex': r'\[SERVER\].*\[(' + UUID_OR_LONG_TASK_REGEX + r')\] - Recognition successful',
        'end_regex': r'\[SERVER\].*\[(' + UUID_OR_LONG_TASK_REGEX + r')\] - Permit released, task finished',
        'id_regex': r'(' + UUID_OR_LONG_TASK_REGEX + r')'
    },
    {
        # Measures the core ML model inference time inside the ImageRecognizer.
        'event_name': 'RECOGNIZER_DETECTION_TIME',
        # CORRECTED: The actual work starts AFTER the artificial delay.
        'start_regex': r'\[SERVER\].*\[(' + UUID_OR_LONG_TASK_REGEX + r')\] - Artificial delay finished\. Starting actual work\.',
        'end_regex': r'\[SERVER\].*I ImageRecognizer: Detection complete.',
        'id_regex': None
    },


    # --- NEW, MORE PRECISE RULES START HERE ---
    {
        # Measures the time from when a task is queued until it acquires a permit to run.
        'event_name': 'SERVER_PERMIT_WAIT_TIME',
        'start_regex': r'\[SERVER\].*\[(' + UUID_OR_LONG_TASK_REGEX + r')\] - Task is now waiting for a permit',
        'end_regex': r'\[SERVER\].*\[(' + UUID_OR_LONG_TASK_REGEX + r')\] - Permit acquired',
        'id_regex': r'(' + UUID_OR_LONG_TASK_REGEX + r')'
    },
    {
        # Measures the time it takes to save the recognition result to the database.
        'event_name': 'RECOGNIZER_DB_SAVE_TIME',
        'start_regex': r'\[SERVER\].*I ImageRecognizer: Detection complete.',
        'end_regex': r'\[SERVER\].*I ImageRecognizer: Recognition result saved to database.',
        'id_regex': None # This is a global, non-task-specific event
    },
    {
        # Measures the time it takes for the ObjectDetector to close after saving the result.
        'event_name': 'RECOGNIZER_CLEANUP_TIME',
        'start_regex': r'\[SERVER\].*I ImageRecognizer: Recognition result saved to database.',
        'end_regex': r'\[SERVER\].*I ImageRecognizer: ObjectDetector has been closed.',
        'id_regex': None # This is also a global, non-task-specific event
    }


]





# Regex to capture the timestamp from any merged log line
TIMESTAMP_REGEX = re.compile(r'(\d{2}:\d{2}:\d{2}\.\d{3})')

def parse_line(line):
    """Parses a single line from the merged log file to extract its timestamp and content."""
    match = TIMESTAMP_REGEX.search(line)
    if not match:
        return None, None

    timestamp_str = match.group(1)
    try:
        # We only need the time part for duration calculation
        dt_obj = datetime.strptime(timestamp_str, '%H:%M:%S.%f')
        return dt_obj, line
    except (ValueError, IndexError):
        return None, None

